private function blocks():void{$pdo=Db::connection();$pageId=(int)($_GET['page_id']??0);$id=(int)($_GET['id']??0);$do=$_GET['do']??'list';if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::validate();if($do==='reorder'){$order=json_decode(file_get_contents('php://input')?:'[]',true)['order']??[];foreach($order as $position=>$blockId){$pdo->prepare('UPDATE blocks SET sort_order=? WHERE id=?')->execute([(int)$position,(int)$blockId]);}Audit::log('reorder','blocks',$pageId);header('Content-Type: application/json');echo json_encode(['ok'=>true]);return;}if($do==='move'){$direction=$_POST['direction']==='up'?-1:1;$current=$this->find($pdo,'blocks',$id);if($current){$stmt=$pdo->prepare('SELECT * FROM blocks WHERE page_id=? AND sort_order '.($direction<0?'<':'>').' ? ORDER BY sort_order '.($direction<0?'DESC':'ASC').' LIMIT 1');$stmt->execute([$pageId,$current['sort_order']]);$other=$stmt->fetch();if($other){$pdo->prepare('UPDATE blocks SET sort_order=? WHERE id=?')->execute([$other['sort_order'],$current['id']]);$pdo->prepare('UPDATE blocks SET sort_order=? WHERE id=?')->execute([$current['sort_order'],$other['id']]);Audit::log('move','blocks',$id);}}header('Location: /admin?action=blocks&page_id='.$pageId);return;}if($do==='delete'){$pdo->prepare('DELETE FROM blocks WHERE id=?')->execute([$id]);Audit::log('delete','blocks',$id);header('Location: /admin?action=blocks&page_id='.$pageId);return;}$type=(string)($_POST['type']??'richtext');$data=match($type){'heading'=>['text'=>(string)($_POST['text']??'')],'image'=>['src'=>(string)($_POST['src']??''),'alt'=>(string)($_POST['alt']??''),'decorative'=>isset($_POST['decorative'])],'links','contact','gallery'=>['items'=>json_decode((string)($_POST['items']??'[]'),true)?:[]],default=>['title'=>(string)($_POST['title']??''),'text'=>(string)($_POST['text']??'')]};$values=[$pageId,$type,(int)($_POST['sort_order']??0),json_encode($data,JSON_UNESCAPED_UNICODE)];if($id){$pdo->prepare('UPDATE blocks SET page_id=?,type=?,sort_order=?,data=? WH