private function media():void{$pdo=Db::connection();$do=$_GET['do']??'list';$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::validate();if($do==='upload'&&isset($_FILES['file'])){$file=$_FILES['file'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/svg+xml'=>'svg'];$mime=mime_content_type($file['tmp_name']);if(!isset($allowed[$mime])||$file['size']>8388608){$error='Nepodporovaný alebo príliš veľký súbor.';}else{$alt=trim((string)($_POST['alt_text']??''));$decorative=isset($_POST['is_decorative']);if($alt===''&&!$decorative){$error='Alt text je povinný, ak obrázok nie je dekoratívny.';}else{$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$dir=dirname(__DIR__,2).'/assets/uploads';if(!is_dir($dir))mkdir($dir,0775,true);move_uploaded_file($file['tmp_name'],$dir.'/'.$name);$pdo->prepare('INSERT INTO media (site_id,path,alt_text,is_decorative,mime) VALUES (?,?,?,?,?)')->execute([(int)($_POST['site_id']??0)?:null,'/assets/uploads/'.$name,$alt,(int)$decorative,$mime]);Audit::log('upload','media',(int)$pdo->lastInsertId());}}}if($do==='delete'){$id=(int)($_POST['id']??0);$pdo->prepare('DELETE FROM media WHERE id=?')->execute([$id]);Audit::log('delete','media',$id);}if(!$error){header('Location: /admin?action=media');return;}}$items=$pdo->query('SELECT * FROM media ORDER BY id DESC')->fetchAll();$e=fn(?string $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$csrf=Csrf::token();require dirname(__DIR__).'/templates/admin/media.php';}
